pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that tracks balances and only allows transferFrom from owner
        SimpleToken token = new SimpleToken();
        address from = address(0x123);
        address to = address(0x456);
        uint amount = 100;
        // fund from address in token
        token.mint(from, amount);
        // approve the C contract to spend from's tokens
        vm.prank(from);
        token.approve(address(c), amount);
        // Create array of recipients
        address[] memory tos = new address[](1);
        tos[0] = to;
        // Now call c.transfer(from, address(token), tos, amount)
        vm.prank(from);
        bool ok;
        try c.transfer(from, address(token), tos, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference version (call), transferFrom succeeds and tokens move
        // In second version (delegatecall), the token's storage context is messed up, causing revert
        assertTrue(ok);
    }
}

contract SimpleToken {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;

    function mint(address to, uint amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "allowance insufficient");
        require(balanceOf[from] >= amount, "balance insufficient");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

